package com.gerenciadorrural.modules.herd.application;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*;
class ListCurrentFarmAnimalsTest { @Test void forwardsOnlyContextTenantAndFarmInsideTransaction(){var tenant=new TenantId(UUID.randomUUID());var context=new TenantContext(tenant,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"OWNER","ALL_FARMS");var called=new boolean[2];HerdAnimalQueryRepository repository=(t,f,q)->{assertThat(called[0]).isTrue();called[1]=true;assertThat(t).isEqualTo(tenant);assertThat(f).isEqualTo(context.farmId());return new HerdAnimalPage(List.of(),q.page(),q.size(),0);};TenantTransactionExecutor tx=new TenantTransactionExecutor(){public <T>T execute(TenantContext c,TenantTransactionalOperation<T> operation){called[0]=true;return operation.execute();}public void execute(TenantContext c,TenantTransactionalAction a){a.execute();}};var page=new ListCurrentFarmAnimals(tx,repository).execute(context,new HerdAnimalQuery("Água",HerdAnimalSex.FEMALE,HerdAnimalStatus.ACTIVE,0,50));assertThat(called).containsExactly(true,true);assertThat(page.totalPages()).isZero();} @Test void rejectsNullContextBeforeRepository(){var useCase=new ListCurrentFarmAnimals(new TenantTransactionExecutor(){public <T>T execute(TenantContext c,TenantTransactionalOperation<T> o){return o.execute();}public void execute(TenantContext c,TenantTransactionalAction a){a.execute();}},(t,f,q)->{throw new AssertionError();});assertThatNullPointerException().isThrownBy(()->useCase.execute(null,new HerdAnimalQuery(null,null,null,0,50)));} }
